<script setup>
import { computed, ref } from 'vue'; import CircuitScene from './components/CircuitScene.vue'; import ComponentLibrary from './components/ComponentLibrary.vue'; import SchematicView from './components/SchematicView.vue'; import { lessons } from './data/lessons';
const tab=ref('ohm'), circuit=ref('led'), running=ref(true), selected=ref(null), view=ref('3d'), placed=ref(['battery','resistor','led']); const lesson=computed(()=>lessons[tab.value]); const readings=computed(()=>circuit.value==='divider'?['4.0 V','40.0 mA','VOUT']:circuit.value==='inverter'?['5.0 V','2.1 mA','OUT: 0']:['9.0 V','18.0 mA','LED ON']); function add(c){placed.value.push(c.id);selected.value=c}
</script>
<template><main class="app-shell"><header class="topbar"><div class="brand"><div class="brand-mark">⌁</div><div><span class="eyebrow">Electronics playground</span><h1>CircuitForge Lab</h1><p>Aprende construyendo, midiendo y preguntando.</p></div></div><button class="button primary" @click="running=!running">{{running?'Ⅱ Pausar':'▶ Ejecutar simulación'}}</button></header><section class="hero-grid"><article class="card intro"><span class="eyebrow">Laboratorio 01 · desde cero</span><h2>La electrónica se entiende cuando la puedes tocar.</h2><p>Explora una mesa 3D, observa cómo circula la corriente y practica con ejemplos seguros.</p><span class="pill">Niños curiosos</span><span class="pill">Adultos principiantes</span><span class="pill">Sin soldar</span></article><section class="card scene-wrap"><CircuitScene/></section></section><section class="editor card"><ComponentLibrary :selected-id="selected?.id" @select="selected=$event" @add="add"/><section class="editor-stage"><div class="stage-toolbar"><div><span class="eyebrow">Editor interactivo</span><h2>{{view==='3d'?'Banco de trabajo 3D':'Diagrama eléctrico'}}</h2></div><div class="view-switch"><button class="mini-button" :class="{active:view==='3d'}" @click="view='3d'">3D</button><button class="mini-button" :class="{active:view==='diagram'}" @click="view='diagram'">Esquema</button></div></div><div class="stage-board"><CircuitScene v-if="view==='3d'"/><SchematicView v-else :circuit="circuit"/><div class="placed-components"><button v-for="(id,i) in placed" :key="`${id}-${i}`" class="placed-chip" @click="selected={id}">{{id.toUpperCase()}} <small>#{{i+1}}</small></button></div></div></section><aside class="inspector"><span class="eyebrow">Inspector</span><h3>{{selected?.name||'Selecciona un componente'}}</h3><p>{{selected?.description||'Elige un elemento para consultar sus pines y propiedades.'}}</p><dl v-if="selected"><div><dt>Valor</dt><dd>{{selected.value||'—'}}</dd></div><div><dt>Pines</dt><dd>{{selected.pins?.join(' · ')||'—'}}</dd></div><div><dt>Estado</dt><dd>Conectable</dd></div></dl></aside></section><section class="work-grid"><section class="card"><div class="panel-head"><h2>Práctica activa</h2><span>{{running?'CIRCUITO ACTIVO':'PAUSADO'}}</span></div><div class="pad"><div class="circuit-grid"><button v-for="x in [['led','LED + resistencia'],['divider','Divisor de voltaje'],['inverter','Inversor NOT']]" :key="x[0]" class="circuit-button" :class="{selected:circuit===x[0]}" @click="circuit=x[0]"><strong>{{x[1]}}</strong></button></div><div class="readings"><div v-for="(r,i) in readings" :key="r"><b>{{r}}</b><small>{{['Fuente DC','Corriente','Salida'][i]}}</small></div></div></div></section><aside class="card lesson"><h3>Ruta de aprendizaje</h3><p>Predice, ejecuta y compara mediciones.</p><ol><li>Observa el circuito.</li><li>Elige una práctica.</li><li>Explica el resultado.</li></ol></aside></section><section class="card education"><nav class="tabs"><button v-for="(_,key) in lessons" :key="key" class="button" :class="{active:tab===key}" @click="tab=key">{{lessons[key].title}}</button></nav><div class="content"><h2>{{lesson.title}}</h2><p>{{lesson.subtitle}}</p><div class="formula">{{lesson.formula}}</div><div class="learn-grid"><article v-for="c in lesson.cards" :key="c.title"><h3>{{c.title}}</h3><p>{{c.body}}</p><code v-if="c.code">{{c.code}}</code></article></div></div></section><footer>Construido con Vue, Vite y Three.js · <a href="https://github.com/uppy19d0/circuitforge-lab" target="_blank">Repositorio en GitHub</a></footer></main></template>
